<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
const rows=ref([]),error=ref(''),busy=ref(false),selected=ref(null),notice=ref('')
const central=ref(false),tenants=ref([]),tenant=ref(''),page=ref(0),orgPage=ref(0)
const form=ref({invoice:'',reference:'',amount_lkr:0,reason:''})
async function load(){error.value='';rows.value=[];selected.value=null;try{if(central.value){if(!tenant.value)return;const result=await request('billing_transport','invoices',{tenant:tenant.value,page:page.value});rows.value=result.invoices}else rows.value=await request('usage_billing','admin_invoices')}catch(e){error.value=e.message}}
async function moreTenants(){try{const next=await request('platform','organizations',{page:orgPage.value},'GET');tenants.value.push(...next.filter(n=>!tenants.value.some(t=>t.name===n.name)));if(next.length)orgPage.value++}catch(e){error.value=e.message}}
function choose(b){selected.value=b;form.value={invoice:b.name,reference:'',amount_lkr:b.amount_lkr,reason:''}}
async function verify(){busy.value=true;error.value='';try{if(central.value)await request('billing_transport','verify_payment',{...form.value,tenant:tenant.value,snapshot:selected.value.snapshot});else await request('usage_billing','verify_and_reactivate',form.value);notice.value='Usage settlement verified. Other overdue invoices or an expired subscription can still restrict access.';selected.value=null;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function init(){try{const session=await request('portal_session','current',{},'GET');central.value=!!session.control_plane;if(central.value)await moreTenants();await load()}catch(e){error.value=e.message}}
onMounted(init)
</script>
<template><section class="panel owner-block"><h2>Provider usage invoices</h2><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="central"><label>Institute<select v-model="tenant" :disabled="busy" @change="page=0;load()"><option value="">Choose an institute</option><option v-for="t in tenants" :key="t.name" :value="t.name">{{t.title}} - {{t.site_hostname}}</option></select></label><button :disabled="busy" @click="moreTenants">Load more institutes</button></div><button :disabled="busy" @click="load">Refresh usage invoices</button><article v-for="b in rows" :key="b.name"><p>{{b.name}} - {{b.subscription}} - {{b.quantity}} active students - LKR {{b.amount_lkr}} - {{b.status}}</p><p v-if="b.activation_requested">Provider requested activation</p><button v-if="b.status==='Unpaid'" :disabled="busy" @click="choose(b)">Review settlement</button></article><div v-if="central && tenant"><button :disabled="busy||page===0" @click="page--;load()">Previous page</button><button :disabled="busy||rows.length<50" @click="page++;load()">Next page</button></div><form v-if="selected" @submit.prevent="verify"><h3>Verify cleared bank funds</h3><p>This records a real settlement. Confirm bank evidence before approval.</p><label>Bank reference<input v-model="form.reference" required maxlength="120"></label><label>Received LKR<input v-model.number="form.amount_lkr" type="number" min="0" step="1" required></label><label>Evidence reviewed<textarea v-model="form.reason" minlength="10" required></textarea></label><button :disabled="busy">Verify payment and approve reactivation</button></form></section></template>
